experiment_code.perttool-mcp-timing-probe.mjs:
// R: Measure actual MCP discovery deadlines in bounded disposable server processes.
import { spawn, spawnSync } from 'node:child_process';
import { performance, monitorEventLoopDelay } from 'node:perf_hooks';
const root='/home/katsumata-m/perttool-worktrees/issue-21-plan-review';
const count=Number(process.argv[2]??1);
let ready=0, release; const barrier=new Promise(resolve=>release=resolve);
const loop=monitorEventLoopDelay({resolution:10}); loop.enable();
async function run(index){
 const start=performance.now(), child=spawn(process.execPath,['--import','/tmp/perttool-mcp-stdio-trace.mjs',root+'/adapters/mcp/dist/main.js'],{cwd:root,stdio:['pipe','pipe','pipe']});
 let buffer='',stderr='',id=0; const pending=new Map(),events=[];
 const exit=new Promise(resolve=>child.once('exit',(code,signal)=>resolve({code,signal})));
 child.stdout.setEncoding('utf8');child.stderr.setEncoding('utf8');child.stderr.on('data',s=>stderr+=s);
 child.stdout.on('data',s=>{buffer+=s;let n;while((n=buffer.indexOf('\n'))>=0){const line=buffer.slice(0,n);buffer=buffer.slice(n+1);const m=JSON.parse(line),p=pending.get(m.id);events.push({kind:'receive',id:m.id,ms:performance.now()-start,late:p?.timedOut??null});if(p){p.resolve(m);clearTimeout(p.timer);pending.delete(m.id);}}});
 function request(method,params){const key=++id,sent=performance.now();events.push({kind:'send',id:key,method,ms:sent-start});return new Promise((resolve,reject)=>{const p={resolve,timedOut:false,timer:setTimeout(()=>{p.timedOut=true;events.push({kind:'deadline',id:key,ms:performance.now()-start});},5000)};pending.set(key,p);p.hard=setTimeout(()=>reject(new Error('hard deadline 15000ms')),15000);p.resolve=m=>{clearTimeout(p.hard);resolve({message:m,elapsed:performance.now()-sent,timedOut:p.timedOut});};child.stdin.write(JSON.stringify({jsonrpc:'2.0',id:key,method,params})+'\n');});}
 try{
 const legacy=await request('initialize',{protocolVersion:'2025-11-25',capabilities:{},clientInfo:{name:'legacy',version:'1.0.0'}});
 if(process.argv[3]){const affinity=spawnSync('taskset',['-pc',process.argv[3],String(child.pid)],{encoding:'utf8'});if(affinity.status!==0)throw new Error(affinity.stderr);}
 if(++ready===count)release();await barrier;
 const discover=await request('server/discover',{_meta:{'io.modelcontextprotocol/protocolVersion':'2026-07-28','io.modelcontextprotocol/clientInfo':{name:'probe',version:'1.0.0'},'io.modelcontextprotocol/clientCapabilities':{}}});
 child.stdin.end(); const closed=await exit;return {index,legacyMs:legacy.elapsed,discoverMs:discover.elapsed,deadlineFired:discover.timedOut,discoveryOk:!!discover.message.result,closed,events,stderr};
 }catch(error){child.kill('SIGTERM');return {index,error:error.message,events,stderr};}
}
const results=await Promise.all(Array.from({length:count},(_,i)=>run(i)));
loop.disable();console.log(JSON.stringify({count,parentLoopMaxMs:loop.max/1e6,results},null,2));

