// R: Timestamp raw stdio events in an owned diagnostic server process.
const trace=(event,fields={})=>process.stderr.write('RCA_TRACE '+JSON.stringify({event,ns:process.hrtime.bigint().toString(),cpu:process.cpuUsage(),...fields})+'\n');
let input='';const emit=process.stdin.emit;
process.stdin.emit=function(event,...args){if(event==='data'){input+=String(args[0]);let n;while((n=input.indexOf('\n'))>=0){const line=input.slice(0,n);input=input.slice(n+1);try{const m=JSON.parse(line);trace('receive',{id:m.id,method:m.method});}catch{trace('non_json_input');}}}return emit.call(this,event,...args);};
const write=process.stdout.write;
process.stdout.write=function(chunk,...args){try{const m=JSON.parse(String(chunk));trace('send',{id:m.id,hasResult:!!m.result,hasError:!!m.error});}catch{}return write.call(this,chunk,...args);};
trace('preload');

