// R: Profile the actual MCP server factory independently from stdio transport.
import inspector from 'node:inspector';
import {performance} from 'node:perf_hooks';
import {writeFileSync} from 'node:fs';
import {createPerttoolMcpAdapter} from '/home/katsumata-m/perttool-worktrees/issue-21-plan-review/adapters/mcp/dist/server.js';
const adapter=createPerttoolMcpAdapter();
const session=new inspector.Session();session.connect();
const post=(method)=>new Promise((resolve,reject)=>session.post(method,(error,result)=>error?reject(error):resolve(result)));
await post('Profiler.enable');await post('Profiler.start');
const cpu=process.cpuUsage(),start=performance.now();const server=adapter.createServer();
const elapsed=performance.now()-start,usage=process.cpuUsage(cpu);
const {profile}=await post('Profiler.stop');session.disconnect();
writeFileSync('/tmp/perttool-mcp-factory.cpuprofile',JSON.stringify(profile));
const byId=new Map(profile.nodes.map(n=>[n.id,n.callFrame]));const totals=new Map();
for(let i=0;i<profile.samples.length;i++){const frame=byId.get(profile.samples[i]);const key=frame.functionName+' '+frame.url+':'+(frame.lineNumber+1);totals.set(key,(totals.get(key)??0)+(profile.timeDeltas[i]??0));}
console.log(JSON.stringify({elapsedMs:elapsed,cpuMs:(usage.user+usage.system)/1000,top:[...totals].sort((a,b)=>b[1]-a[1]).slice(0,15)},null,2));
await server.close();

