        reads.push(sourcePath);
        return bytes;
      },
    },
    bundledArtifacts: { read: forbidden },
    gitEvidence: {
      probeHistory: forbidden,
      captureAdvanceBaseline: forbidden,
      recheckAdvanceBaseline: forbidden,
